using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
class V5Tests {
 static int failures;static void Check(string n,bool pass){Console.WriteLine((pass?"PASS ":"FAIL ")+n);if(!pass)failures++;}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Invoke(object o,string n,params object[] a){o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}
 static Button Button(DependencyObject root,string name){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);var b=child as Button;if(b!=null&&Convert.ToString(b.Content)==name)return b;var found=Button(child,name);if(found!=null)return found;}return null;}
 static void Shot(Window w,string path){w.UpdateLayout();var c=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)c.ActualWidth,(int)c.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(c);var p=new PngBitmapEncoder();p.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))p.Save(f);}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{
  Check("idle threshold",ActivityLogic.State(false,false,false,89)=="awake"&&ActivityLogic.State(false,false,false,90)=="sleep");Check("focus prevents sleep",ActivityLogic.State(false,true,false,200)=="awake");Check("interaction wakes pet",ActivityLogic.State(false,false,true,200)=="awake");Check("search wins over idle and focus",ActivityLogic.State(true,true,false,200)=="search");
  string fixtures=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"search-fixtures");Directory.CreateDirectory(Path.Combine(fixtures,"nested"));File.WriteAllText(Path.Combine(fixtures,"report.txt"),"x");File.WriteAllText(Path.Combine(fixtures,"nested","REPORT.csv"),"y");File.WriteAllText(Path.Combine(fixtures,"other.txt"),"z");var result=FileFinder.Search(fixtures,"report",CancellationToken.None);Check("real recursive case insensitive filename search",result.Files.Count==2&&result.Scanned==3);Check("empty result",FileFinder.Search(fixtures,"missing",CancellationToken.None).Files.Count==0);var canceled=new CancellationTokenSource();canceled.Cancel();bool stopped=false;try{FileFinder.Search(fixtures,"report",canceled.Token);}catch(OperationCanceledException){stopped=true;}Check("cancel stops traversal",stopped);
  string many=Path.Combine(fixtures,"many");Directory.CreateDirectory(many);for(int i=0;i<205;i++)File.WriteAllText(Path.Combine(many,"item"+i+".txt"),"");result=FileFinder.Search(many,"item",CancellationToken.None);Check("results bounded to 200",result.Limited&&result.Files.Count==200);
  pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((VoiceRuntime)Field(pet,"voices")).Settings.Volume=.01;Invoke(pet,"OpenTerminal");var terminal=(TerminalWindow)Field(pet,"terminal");
  foreach(string page in new[]{"文件与启动","效率工具","开发助手","计划与专注","文件搜索","快捷入口","进程监控","系统与网络","Codex状态","通知记录","待办计划","专注","提醒","健康","便签","文本","剪贴板","桌面工具","文件观察","磁盘与电池","语音与快捷键","便签","总览","动作与移动"}){terminal.ShowPage(page);terminal.UpdateLayout();Check("single workbench route "+page,terminal.IsVisible);}
  var skillsWindow=(SkillsWindow)Field(pet,"skillsWindow");var skillRuntime=(SkillRuntime)Field(pet,"skills");var advanced=(AdvancedRuntime)Field(pet,"advanced");terminal.ShowPage("便签");terminal.UpdateLayout();((TextBox)Field(skillsWindow,"noteTitle")).Text="v5测试便签";((TextBox)Field(skillsWindow,"noteText")).Text="嵌入页面实际保存";Button(terminal,"保存便签").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Check("embedded note saves actual data",skillRuntime.Engine.Data.Notes.Any(n=>n.Title=="v5测试便签"));Check("embedded note persists",new SkillRuntime(AppDomain.CurrentDomain.BaseDirectory).Engine.Data.Notes.Any(n=>n.Title=="v5测试便签"));terminal.ShowPage("待办计划");terminal.UpdateLayout();((TextBox)Field(skillsWindow,"taskTitle")).Text="v5测试任务";Button(terminal,"添加待办").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Check("embedded task creates real task",advanced.Engine.Data.Tasks.Any(t=>t.Title=="v5测试任务"));
  Check("tool windows stay hidden",!((Window)Field(pet,"assistantWindow")).IsVisible&&!((Window)Field(pet,"skillsWindow")).IsVisible);
  var tray=(System.Windows.Forms.NotifyIcon)Field(pet,"tray");var entries=tray.ContextMenuStrip.Items.OfType<System.Windows.Forms.ToolStripMenuItem>().ToArray();Check("compact menu has one dedicated action list",entries.Length==10&&entries.Count(entry=>entry.HasDropDownItems)==1&&entries.Single(entry=>entry.HasDropDownItems).Text=="动作选择");Check("menu labels unique",entries.Select(entry=>entry.Text).Distinct().Count()==entries.Length);
  var ticker=(DispatcherTimer)Field(pet,"ticker");Check("60Hz scheduler",ticker.Interval.TotalMilliseconds<=17);Check("run cadence uses slower distance stride",ActionTiming.WalkStride==96&&PetLogic.Durations[1].Length==8);
  Invoke(pet,"DisplayExtra",0,0.0,220);var sprite=(SpriteView)Field(pet,"sprite");Check("sleep sheet loaded",sprite.Frame.PixelWidth==192&&sprite.Frame.PixelHeight==208);var sleep=sprite.Frame;Invoke(pet,"DisplayExtra",0,.25,220);Check("sleep advances distinct frame",!Object.ReferenceEquals(sleep,sprite.Frame));Invoke(pet,"DisplayExtra",8,0.0,85);Check("magnifier differs from sleep",!Object.ReferenceEquals(sleep,sprite.Frame));
  typeof(ConanPet).GetField("searching",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(pet,true);typeof(ConanPet).GetField("actionUntil",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(pet,0.0);double x=pet.Left,y=pet.Top;Invoke(pet,"Tick",null,EventArgs.Empty);Check("search stops movement and renders new sheet",pet.Left==x&&pet.Top==y&&sprite.Frame.PixelWidth==192&&sprite.Frame.PixelHeight==208);typeof(ConanPet).GetField("searching",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(pet,false);
  terminal.ShowPage("文件搜索");terminal.UpdateLayout();var view=(FileSearchView)Field(terminal,"fileSearch");((TextBox)Field(view,"folder")).Text=fixtures;((TextBox)Field(view,"query")).Text="report";Invoke(view,"Begin");Check("real search activates pet",(bool)Field(pet,"searching"));var frame=new DispatcherFrame();var timeout=DateTime.UtcNow.AddSeconds(8);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(s,e)=>{if(!(bool)Field(pet,"searching")||DateTime.UtcNow>timeout){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);Check("search completion clears pet activity",!(bool)Field(pet,"searching"));Check("GUI receives actual matches",((ListBox)Field(view,"results")).Items.Count==2);
  Directory.CreateDirectory(args[0]);for(int kind=0;kind<2;kind++)for(int i=0;i<8;i++){Invoke(pet,"DisplayExtra",kind*8,i*(kind==0?.22:.14)+.01,kind==0?220:140);pet.UpdateLayout();var shot=new RenderTargetBitmap((int)sprite.ActualWidth,(int)sprite.ActualHeight,96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen())dc.DrawRectangle(new VisualBrush(sprite){Stretch=Stretch.Fill},null,new Rect(0,0,shot.PixelWidth,shot.PixelHeight));shot.Render(drawing);var encoded=new PngBitmapEncoder();encoded.Frames.Add(BitmapFrame.Create(shot));using(var f=File.Create(Path.Combine(args[0],"v5.5-"+(kind==0?"sleep":"search")+"-"+i.ToString("D2")+".png")))encoded.Save(f);}foreach(string page in new[]{"总览","文件与启动","效率工具","文件搜索","便签","动作与移动"}){terminal.ShowPage(page);Shot(terminal,Path.Combine(args[0],"v5-"+page+".png"));}terminal.Width=1000;terminal.Height=700;terminal.ShowPage("待办计划");Shot(terminal,Path.Combine(args[0],"v5-compact.png"));Check("compact real page fits workbench",terminal.ActualWidth==1000);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}Console.WriteLine("Failures: "+failures);return failures==0?0:1;}
}
